import{_ as e,c as t,o as i,b0 as s}from"./chunks/framework.C5ev1SXp.js";const o="data:image/png;base64,",n="/scm-docs/assets/image-20230525220139469.Ec7ZY2xO.png",r="/scm-docs/assets/image-20230525220645287.BbrOmdeX.png",l="/scm-docs/assets/898333-20160321075601261-2034959313.DHe01qSD.png",p="/scm-docs/assets/898333-20160321075618870-635504064.SboK-O8q.png",d="/scm-docs/assets/898333-20160321075644370-1557215574.BTjoaCpd.png",c="data:image/png;base64,",h="data:image/png;base64,",g="/scm-docs/assets/image-20241016224621170.DrNixnK3.png",A="/scm-docs/assets/webp.Cck9bbZy.webp",m="/scm-docs/assets/webp-1729090813421-16.wBvS4LWe.webp",C="/scm-docs/assets/image-20241016230406782.B_qq8QhP.png",I="/scm-docs/assets/898333-20160321075816636-532313423.BE-gQ-SJ.png",b="/scm-docs/assets/898333-20160321075827808-16244704.eJ5ym4OI.png",u="/scm-docs/assets/898333-20160321075839808-450676409.CS9Ze7Aa.png",B="/scm-docs/assets/image-20230525221451347.DNbhO49l.png",x="/scm-docs/assets/image-20230525221645986.BCyFcUI5.png",F="/scm-docs/assets/image-20230525222244771.GWjJ8mYq.png",U="/scm-docs/assets/image-20230525222627935.C0Mpy7Ex.png",k="/scm-docs/assets/image-20230525223249093.7GTir-S2.png",q="/scm-docs/assets/image-20230525224955849.B-W3TH0-.png",S="/scm-docs/assets/image-20230525224416558.DdMIVYNu.png",f="/scm-docs/assets/image-20230525225400864.BxhaU4uJ.png",E="/scm-docs/assets/image-20230525225601376.HH5A7Cba.png",T="/scm-docs/assets/image-20230525225937673.BQGhR3zA.png",G="/scm-docs/assets/image-20230525230130328.BLnxF16r.png",N="/scm-docs/assets/image-20230525232151415.D47RMEZZ.png",y="/scm-docs/assets/image-20230525230541353.Bn18MMw4.png",K="/scm-docs/assets/image-20230525230717931.C-729mIr.png",v="/scm-docs/assets/image-20230525231341589.Ba1VWnJH.png",w="/scm-docs/assets/image-20230525231656845.E0HA4Fsb.png",V="data:image/png;base64,",D="/scm-docs/assets/image-20230525232454881.nZFXb5rN.png",Y=JSON.parse('{"title":"LV030-字符编码基础","description":null,"frontmatter":{"title":"LV030-字符编码基础","date":"2025-09-27T19:14:24.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/display/lcd/126b095255800a53f67e99cc","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-27T19:14:24.165Z","fulluuid":"3f67e99cc1774328be76eff3ae429948","useduuid":"3f67e99cc"}},"headers":[],"relativePath":"sdoc/advanced-chapter/display/lcd/126b095255800a53f67e99cc.md","filePath":"sdoc/30-进阶篇/04-显示屏/02-LCD/LV030-字符编码简介.md","lastUpdated":1766591892000}'),P={name:"sdoc/advanced-chapter/display/lcd/126b095255800a53f67e99cc.md"};function Q(_,a,z,M,R,X){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="lv030-字符编码基础" tabindex="-1">LV030-字符编码基础 <a class="header-anchor" href="#lv030-字符编码基础" aria-label="Permalink to &quot;LV030-字符编码基础&quot;">​</a></h1><h2 id="一、字符编码概述" tabindex="-1">一、字符编码概述 <a class="header-anchor" href="#一、字符编码概述" aria-label="Permalink to &quot;一、字符编码概述&quot;">​</a></h2><p>在计算机上，我们看到的字符“ A”可能长这样 ：</p><img src="'+o+'" alt="image-20230525215626795" style="zoom:50%;"><p>对于同一个 TXT 文件中的内容，我们在 Notepad++ 上选择不同字体时，字符显示的形状也可能不一样。 所以 TXT 文件中保存的是字符的核心：它的编码值。而 Notepad++ 上显示时，这些字符对应什么样的形状态，这是由字符文件决定的。</p><p>编码值，字体是两个不一样的东西，比如 A 的编码值是 0x41，但是在屏幕上显示出来时可以使用不同的形状。什么叫编码？就是一个字符用什么数字来表示。在计算机里一切都是用数字来表示，比如字符 A，用 0x01 还是 0x02 来表示它？我们使用 0x41 来表示它。当我们去打开一个 TXT 文件时，发现里面含有数值 0x41，我们就知道了：哦，这里有一个字符 A。</p><p>一个字符用哪个数字来表示？有很多标准 ，我们这就来了解一下吧。</p><h2 id="二、ascii编码" tabindex="-1">二、ASCII编码 <a class="header-anchor" href="#二、ascii编码" aria-label="Permalink to &quot;二、ASCII编码&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>由于计算机只能识别0和1，文字也只能以0和1的形式在计算机里存储，所以我们需要对文字进行编码才能让计算机处理，编码的过程就是规定特定的01数字串来表示特定的文字，最简单的字符编码例子是ASCII码。</p><p>ASCII码，就是“American Standard Code for Information Interchange”的缩写， 美国信息交换标准代码。电脑毕竟是西方人发明的，他们常用字母就 26 个，区分大小写、加上标点符号也没超过 127 个，每个字符用一个字节来表示就足够了。一个字节的 7 位就可以表示 128 个数值，所以在 ASCII 码中最高位永远是 0。</p><p>在程序设计中使用的ASCII编码表约定了一些控制字符、英文及数字。它们在存储器中，本质也就是二进制数，只是我们约定这些二进制数可以表示某些特殊意义，如以ASCII编码解释数字“0x41”时，它表示英文字符“A”。</p><h3 id="_2-ascii编码表" tabindex="-1">2. ASCII编码表 <a class="header-anchor" href="#_2-ascii编码表" aria-label="Permalink to &quot;2. ASCII编码表&quot;">​</a></h3><img src="'+n+'" alt="image-20230525220139469" style="zoom:50%;"><p>ASCII码表分为两部分：</p><p>（1）第一部分是控制字符或通讯专用字符，它们的数字编码从0~31，它们并没有特定的图形显示，但会根据不同的应用程序，而对文本显示有不同的影响。</p><p>（2）的第二部分包括空格、阿拉伯数字、标点符号、大小写英文字母以及“DEL（删除控制）”，这部分符号的数字编码从32~127，除最后一个DEL符号外，都能以图形的方式来表示，它们属于传统文字书写系统的一部分。</p><h2 id="三、ansi编码" tabindex="-1">三、ANSI编码 <a class="header-anchor" href="#三、ansi编码" aria-label="Permalink to &quot;三、ANSI编码&quot;">​</a></h2><h3 id="_1-记事本保存没有ascii" tabindex="-1">1. 记事本保存没有ASCII？ <a class="header-anchor" href="#_1-记事本保存没有ascii" aria-label="Permalink to &quot;1. 记事本保存没有ASCII？&quot;">​</a></h3><p>我们打开记事本，保存一个文件，并指定编码方式：</p><img src="'+r+'" alt="image-20230525220645287" style="zoom:67%;"><p>使用记事本保存文件时，可以选择“ ANSI”编码，却没有“ ASCII”，这是怎么回事？</p><h3 id="_2-asni简介" tabindex="-1">2. ASNI简介 <a class="header-anchor" href="#_2-asni简介" aria-label="Permalink to &quot;2. ASNI简介&quot;">​</a></h3><h4 id="_2-1-ansi是什么编码" tabindex="-1">2.1 ANSI是什么编码 <a class="header-anchor" href="#_2-1-ansi是什么编码" aria-label="Permalink to &quot;2.1 ANSI是什么编码&quot;">​</a></h4><p>这部分主要参考<a href="https://www.cnblogs.com/malecrab/p/5300486.html" target="_blank" rel="noreferrer">ANSI是什么编码？ - malecrab - 博客园 (cnblogs.com)</a>，防止原文找不到，这里自己做一遍笔记备份一下。</p><p>用Notepad++创建一个文本文件text.txt，其默认编码格式为ANSI（不仔细看还以为是ASCII），输入汉字居然不是乱码：</p><img src="'+l+'" alt="img"><p>保存为test.txt，发送给自己美国的同事Bob（假装有这么一个同事）。他也用Notepad++，不幸的是，却发现我们的文件内容是这样的：</p><img src="'+p+'" alt="img"><p>也许我们会认为：我们用的是中文系统，能正常显示中文；他用的是英文系统，不能显示中文！这么想，是不是很有道理。但是再细想一下：<strong>一个系统显示乱码，说明它不支持这种编码格式（或者解码方式不对）。难道英文系统不支持ANSI？难道ANSI是一种中文编码？</strong></p><p>如果我们身边有一个韩文系统，也装一个Notepad++，默认还是ANSI编码，我们可以输入“한국어”，发现也能正常显示：</p><img src="'+d+'" alt="img"><p>但是我们要输入“汉字”可能就会发现是乱码了。通过这个反例，就可以说明<strong>ANSI不是一种中文编码。那么，ANSI到底是什么编码？</strong></p><p>用十六进制编辑器打开内容为“汉字”的test.txt文件：</p><img src="'+c+'" alt="img"><p>会发现：其中baba和d7d6正好是“汉”和“字”两个字的<a href="https://www.qqxiuzi.cn/zh/hanzi-gbk-bianma.php" target="_blank" rel="noreferrer">GBK 编码</a>值。同样，用十六进制编辑器打开内容为“한국어”的test.txt文件：</p><img src="'+h+'" alt="img"><p>会发现：其中c7d1、b1b9和beee正好是“한”、“국”和“어”三个字符的EUC-KR编码值。</p><p>由此可以看出：其实ANSI并不是某一种特定的字符编码，而是在不同的系统中，ANSI表示不同的编码。我们美国同事Bob的系统中ANSI编码其实是ASCII编码（ASCII编码不能表示汉字，所以汉字为乱码），而我们的系统中（“汉字”正常显示）ANSI编码其实是GBK编码，而韩文系统中（“한국어”正常显示）ANSI编码其实是EUC-KR编码。</p><blockquote><p>一个类似野史的小故事：</p><p>话说计算机是由美国佬搞出来的嘛，他们觉得一个字节（可以表示256个编码）表示英语世界里所有的字母、数字和常用特殊符号已经绰绰有余了（其实ASCII只用了前127个编码）。后来欧洲人不干了，法国人说：我需要在小写字母加上变音符号（如：é），德国人说：我也要加几个字母（Ä ä、Ö ö、Ü ü、ß）。于是，欧洲人就将ASCII没用完的编码（128-255）为自己特有的符号编码（后来称之为“扩展字符集”）。等到我们中国人开始使用计算机的时候，尼玛，256个编码哪够？我泱泱大中华，汉字起码也得N多万吧，就连小学生都得要求掌握两三千字。国标局最后拍板：一个字节不够，那我们就用多个字节来为汉字编码吧，但是，国情那么穷，字节那么贵，三个字节伤不起，那就用俩字节吧，先给常用的几千汉字编个码，等以后国家强盛了人民富裕了，咱再扩展呗---于是GB2312就产生了。台湾同胞一看，尼玛，全是简体字，还让不让我们写繁体字的活了，于是台湾同胞也自己弄了个繁体字编码---大五码（Big-5）。同时，其它国家也在为自己的文字编码。最后，微软苦逼了：顾客就是上帝啊，你们的编码我都得满足啊，这样吧，卖给美国国内的系统默认就用ASCII编码吧，卖给中国人的系统默认就用GBK编码吧，卖给韩国人的系统默认就用EUC-KR编码，...但是为了避免你们误会我卖给你们的系统功能有差异，我就统一把你们的默认编码都显示成ANSI吧。---本故事纯属虚构，但“ANSI编码”确实只存在于Windows系统。</p></blockquote><p>所以其实ASNI 是 ASCII 的扩展，向下包含 ASCII。对于 ASCII 字符仍以一个字节来表示，对于非 ASCII 字符则使用 2 字节来表示。并没有固定的 ASNI 编码，它跟“**本地化”(local)**密切相关。比如在中国大陆地区， ANSI 的默认编码是 GBK；在港澳台地区默认编码是 BIG5。以数值“ 0xd0d6”为例，对于 GB2312 编码它表示“中”；对于 BIG5 编码它表示“ 笢”。</p><h4 id="_2-2-windows如何区分" tabindex="-1">2.2 Windows如何区分？ <a class="header-anchor" href="#_2-2-windows如何区分" aria-label="Permalink to &quot;2.2 Windows如何区分？&quot;">​</a></h4><blockquote><p>那么Windows系统是如何区分ANSI背后的真实编码的呢？</p></blockquote><p>微软用一个叫“<a href="https://en.wikipedia.org/wiki/Code_page" target="_blank" rel="noreferrer">Windows code pages</a>”（在命令行下执行chcp命令可以查看当前code page的值）的值来判断系统默认编码，比如：简体中文的code page值为936（它表示GBK编码，win95之前表示GB2312，详见：<a href="https://en.wikipedia.org/wiki/Code_page_1386" target="_blank" rel="noreferrer">Microsoft Windows&#39; Code Page 936</a>），繁体中文的code page值为950（表示Big-5编码）。</p><img src="'+g+'" alt="image-20241016224621170"><p>我们能否通过修改Windows code pages的值来改变“ANSI编码”呢？命令提示符下，我们可以通过chcp命令来修改当前终端的active code page，例如：</p><p>(1) 执行：chcp 437，code page改为437，当前终端的默认编码就为ASCII编码了（汉字就成乱码了）；</p><p>(2) 执行：chcp 936，code page改为936，当前终端的默认编码就为GBK编码了（汉字又能正常显示了）。</p><p>上面的操作只在当前终端起作用，并不会影响系统默认的“ANSI编码”。若是之前是无法使用 chcp 命令，可以这样操作：打开注册表编辑器，定位到这里路径（网上找的，但是我的是win11，似乎没有这一项，这里大概了解一下就是了）：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">计算机\\HKEY_CURRENT_USER\\Console%SystemRoot%_system32_cmd.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+A+'" alt="img"><blockquote><p>说明：</p><p>十六进制&quot;000003a8&quot;或十进制&quot;936&quot;，表示“936 (ANSI/OEM - 简体中文 GBK)”。</p><p>十六进制&quot;000001b5&quot;或十进制&quot;437&quot;，表示“437 (OEM - 美国)”。</p></blockquote><p>通过修改注册表的这一项后，重新打开一个 cmd 窗口，输入 &quot;chcp&quot;就能显示当前的活动代码页面了。<strong>重新打开一个 cmd 窗口，又会改为默认的 936 编码</strong>，这只是权宜之计。如何永久修改？我们打开到这一项：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">计算机\\HKEY_CURRENT_USER\\Software\\Microsoft\\Command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Processor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>添加 autorun 字符串值:</p><img src="'+m+'" alt="img"><p>现在无论你什么时候运行 cmd 命令行（哪怕是任意程序，调用 cmd 程序运行一些指令）都会默认使用 UTF-8 的编码显示了。<strong>如果需要显示特殊字体，修改编码后仍然无法正常显示，则需要额外安装命令行字体</strong>，另外这里如果影响某些程序运行，可以删除这第二处注册表的值。</p><p>那图形界面能改吗？也可以，Windows下code page是根据当前系统区域（locale）来设置的，要想修改系统默认的“ANSI编码”，我们可以通过修改系统区域来实现（“控制面板” →“时钟、语言和区域”→“区域和语言”→“管理”→“更改系统区域设置”）：</p><img src="'+C+'" alt="image-20241016230406782" style="zoom:50%;"><p>图中的系统locale为简体中文，意味着当前“ANSI编码”实际是GBK编码。当把它改成Korean(Korea)时，“ANSI编码”实际是EUC-KR编码，“한국어”就能正常显示了；当把它改成English(US)时，“ANSI编码”实际是ASCII编码，“汉字”和“한국어”都成乱码了。（改了之后需要重启系统的）</p><p>说明：locale是国际化与本地化中重要的概念，这里就不再更深入了解了。</p><h4 id="_2-3-linux呢" tabindex="-1">2.3 linux呢？ <a class="header-anchor" href="#_2-3-linux呢" aria-label="Permalink to &quot;2.3 linux呢？&quot;">​</a></h4><p>将前述内容为“汉字”的文件test.txt拷贝至Linux下，用Emacs打开：</p><img src="'+I+'" alt="img"><p>也是乱码！原因也是locale的问题：</p><img src="'+b+'" alt="img" style="zoom:88%;"><p>更改locale后再打开：</p><img src="'+u+'" alt="img" style="zoom:80%;"><h3 id="_3-具体编码" tabindex="-1">3. 具体编码 <a class="header-anchor" href="#_3-具体编码" aria-label="Permalink to &quot;3. 具体编码&quot;">​</a></h3><p>通过对上面的了解，我们知道对于 ANSI 编码的 TXT 文件，如果我们打开它发现乱码，那么还得再次细分它的具体编码。我们新建一个ANSI编码的txt文本文档，并输入以下数据：</p><img src="'+B+'" alt="image-20230525221451347" style="zoom:50%;"><p>然后我们通过Notepad++打开，为什么用这个软件？因为它可以很方便的帮我们转换各种字符编码：</p><img src="'+x+'" alt="image-20230525221645986" style="zoom:50%;"><p>我们查看文件的十六进制编码的话需要装一个插件，名字叫HEX-Editor，安装完毕后，我们就可以将文件内容编程十六进制的形式显示啦，就像上图。我们现在选择不同的编码格式打开这个文件：</p><img src="'+F+'" alt="image-20230525222244771" style="zoom:80%;"><p>这仅仅是在中国地区就出现这些不兼容的问题。对于不同国家，它们默认的ANSI 编码各不相同，所以同一个 TXT 文件在不同国家就很有可能出现乱码。根本的原理在于没有“统一的编码”，那解决方法自然就是使用“统一的编码”： UNICODE。这个我们后面再详细说。</p><h2 id="四、中文编码" tabindex="-1">四、中文编码 <a class="header-anchor" href="#四、中文编码" aria-label="Permalink to &quot;四、中文编码&quot;">​</a></h2><h3 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h3><p>英文书写系统都是由26个基本字母组成，利用26个字母组可合出不同的单词，所以用ASCII码表就能表达整个英文书写系统。而中文书写系统中的汉字是独立的方块，若参考单词拆解成字母的表示方式，汉字可以拆解成部首、笔画来表示，但这样会非常复杂(可参考五笔输入法编码)，所以中文编码直接对方块字进行编码，一个汉字使用一个号码。</p><p>由于汉字非常多，常用字就有6000多个，如果像ASCII编码表那样只使用1个字节最多只能表示256个汉字，所以我们使用2个字节来编码。</p><h3 id="_2-gb2312标准" tabindex="-1">2. GB2312标准 <a class="header-anchor" href="#_2-gb2312标准" aria-label="Permalink to &quot;2. GB2312标准&quot;">​</a></h3><h4 id="_2-1-简介" tabindex="-1">2.1 简介 <a class="header-anchor" href="#_2-1-简介" aria-label="Permalink to &quot;2.1 简介&quot;">​</a></h4><p>我国首先定义的是GB2312标准。它把ASCII码表127号之后的扩展字符集直接取消掉，并规定小于127的编码按原来ASCII标准解释字符。当2个大于127的字符连在一起时，就表示1个汉字，第1个字节使用 (0xA1-0xFE) 编码，第2个字节使用(0xA1-0xFE)编码，这样的编码组合起来可以表示了7000多个符号，其中包含6763个汉字。可以看到从 0x7F 到 0xA1 中间其实还是有空余的，这一部分在GB2312中没有使用。</p><p>在这些编码里，我们还把数学符号、罗马字母、日文假名等都编进表中，<strong>就连原来在ASCII里原本就有的数字、标点以及字母也重新编了2个字节长的编码</strong>，这就是平时在输入法里可切换的“全角”字符，而标准的ASCII码表中127号以下的就被称为“半角”字符。</p><img src="'+U+'" alt="image-20230525222627935" style="zoom:50%;"><h4 id="_2-2-兼容ascii" tabindex="-1">2.2 兼容ASCII？ <a class="header-anchor" href="#_2-2-兼容ascii" aria-label="Permalink to &quot;2.2 兼容ASCII？&quot;">​</a></h4><p>下表说明了GB2312是如何兼容ASCII码的，当我们设定系统使用GB2312标准的时候，它遇到一个字符串时，会按字节检测字符值的大小，若遇到连续两个字节的数值都大于127（0x7F）时就把这两个连续的字节合在一起，用GB2312解码，若遇到的数值小于127（0x7F），就直接用ASCII把它解码。</p><table tabindex="0"><thead><tr><th style="text-align:center;">第1字节</th><th style="text-align:center;">第2字节</th><th style="text-align:center;">表示的字符</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">0x68</td><td style="text-align:center;">0x69</td><td style="text-align:center;">(hi)</td><td>两个字节的值都小于127(0x7F)，使用ASCII解码</td></tr><tr><td style="text-align:center;">0xB0</td><td style="text-align:center;">0xA1</td><td style="text-align:center;">(啊)</td><td>两个字节的值都大于127(0x7F)，使用GB2312解码</td></tr></tbody></table><h4 id="_2-3-区位码" tabindex="-1">2.3 区位码 <a class="header-anchor" href="#_2-3-区位码" aria-label="Permalink to &quot;2.3 区位码&quot;">​</a></h4><p>在 GB2312 编码的实际使用中，有时会用到区位码的概念。GB2312编码对所收录字符进行了“分区”处理，共94个区，每区含有94个位，共8836个码位。</p><p>区位码实际是GB2312编码的内部形式，它规定对收录的每个字符采用两个字节表示：第一个字节为“高字节”，对应94个区；第二个字节为“低字节”，对应94个位。所以它的区位码范围是：0101-9494。</p><p>为兼容ASCII码，区号和位号分别加上0xA0偏移就得到GB2312编码。在区位码上加上0xA0偏移，可求得GB2312编码范围：0xA1A1－0xFEFE，其中汉字的编码范围为0xB0A1-0xF7FE，第一字节0xB0-0xF7（对应区号：16－87），第二个字节0xA1-0xFE（对应位号：01－94）。</p><p>例如，“啊”字是GB2312编码中的第一个汉字，它位于16区的01位，所以它的区位码就是1601，加上0xA0偏移，其GB2312编码为0xB0A1。其中区位码为0101的码位表示的是“空格”符。我们可以看一下<a href="https://www.qqxiuzi.cn/zh/hanzi-gb2312-bianma.php" target="_blank" rel="noreferrer">GB2312 编码范围, GB2312 编码表 (qqxiuzi.cn)</a>这个网站这里的趣味码表：</p><img src="'+k+`" alt="image-20230525223249093" style="zoom:50%;"><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">A0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">B0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">A0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">A1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-gbk标准" tabindex="-1">3. GBK标准 <a class="header-anchor" href="#_3-gbk标准" aria-label="Permalink to &quot;3. GBK标准&quot;">​</a></h3><h4 id="_3-1-简介" tabindex="-1">3.1 简介 <a class="header-anchor" href="#_3-1-简介" aria-label="Permalink to &quot;3.1 简介&quot;">​</a></h4><p>据统计，GB2312编码中表示的6763个汉字已经覆盖中国大陆99.75%的使用率，单看这个数字已经很令人满意了，但是不能因为那些文字不常用就不让它进入信息时代，而且生僻字在人名、文言文中的出现频率是非常高的。</p><p>为此我们在GB2312标准的基础上又增加了14240个新汉字(包括所有后面介绍的Big5中的所有汉字)和符号，这个方案被称为GBK标准。增加这么多字符，按照GB2312原来的格式来编码，2个字节已经存储不下，我们的程序员修改了一下格式，不再要求第2个字节的编码值必须大于127，只要第1个字节大于127就表示这是一个汉字的开始，这样就做到兼容ASCII和GB2312标准了。</p><h4 id="_3-2-兼容gb2312" tabindex="-1">3.2 兼容GB2312？ <a class="header-anchor" href="#_3-2-兼容gb2312" aria-label="Permalink to &quot;3.2 兼容GB2312？&quot;">​</a></h4><p>下表说明了GBK是如何兼容ASCII和GB2312标准的，当我们设定系统使用GBK标准的时候，它按顺序遍历字符串，按字节检测字符值的大小，若遇到一个字符的值大于127时，就再读取它后面的一个字符，把这两个字符值合在一起，用GBK解码，解码完后，再读取第3个字符，重新开始以上过程，若该字符值小于127，则直接用ASCII解码。</p><table tabindex="0"><thead><tr><th style="text-align:center;">第1字节</th><th style="text-align:center;">第2字节</th><th style="text-align:center;">第3字节</th><th style="text-align:center;">表示的字符</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">0x68(&lt;7F)</td><td style="text-align:center;">0xB0(&gt;7F)</td><td style="text-align:center;">0xA1(&gt;7F)</td><td style="text-align:center;">(h啊)</td><td>第1个字节小于127，使用ASCII解码，每2个字节大于127，直接使用GBK解码，兼容GB2312</td></tr><tr><td style="text-align:center;">0xB0(&gt;7F)</td><td style="text-align:center;">0xA1(&gt;7F)</td><td style="text-align:center;">0x68(&lt;7F)</td><td style="text-align:center;">(啊h)</td><td>第1个字节大于127，直接使用GBK码解释，第3个字节小于127，使用ASCII解码</td></tr><tr><td style="text-align:center;">0xB0(&gt;7F)</td><td style="text-align:center;">0x56(&lt;7F)</td><td style="text-align:center;">0x68(&lt;7F)</td><td style="text-align:center;">(癡h)</td><td>第1个字节大于127，第2个字节虽然小于127，直接使用GBK解码，第3个字节小于127，使用ASCII解码</td></tr></tbody></table><h4 id="_3-3-区位码" tabindex="-1">3.3 区位码 <a class="header-anchor" href="#_3-3-区位码" aria-label="Permalink to &quot;3.3 区位码&quot;">​</a></h4><p>与GB2312一样，GBK编码也有区位码，我们可以参考这里：<a href="https://www.qqxiuzi.cn/zh/hanzi-gbk-bianma.php" target="_blank" rel="noreferrer">GBK 编码范围, GBK 编码表 (qqxiuzi.cn)</a>，上边我们知道每个GBK码由2个字节组成，第一个字节为0X81~0XFE，第二个字节分为两部分，一是0X40~0X7E，二是0X80~0XFE。我们把第一个字节代表的意义称为区，那么GBK里面总共有126个区（0XFE-0X81+1），每个区内有190个汉字（0XFE-0X80+0X7E-0X40+2），总共就有126*190=23940个汉字。</p><img src="`+q+'" alt="image-20230525224955849" style="zoom:50%;"><h3 id="_4-gb18030标准" tabindex="-1">4. GB18030标准 <a class="header-anchor" href="#_4-gb18030标准" aria-label="Permalink to &quot;4. GB18030标准&quot;">​</a></h3><p>随着计算机技术的普及，我们后来又在GBK的标准上不断扩展字符，这些标准被称为GB18030，如GB18030-2000、GB18030-2005等(“-”号后面的数字是制定标准时的年号)，GB18030的编码使用4个字节，它利用前面标准中的第2个字节未使用的“0x30-0x39”编码表示扩充四字节的后缀，兼容GBK、GB2312及ASCII标准。</p><p>GB18030-2000主要在GBK基础上增加了“CJK(中日韩)统一汉字扩充A”的汉字。加上前面GBK的内容，GB18030-2000一共规定了27533个汉字（包括部首、部件等）的编码，还有一些常用非汉字符号。</p><p>GB18030-2005的主要特点是在GB18030-2000基础上增加了“CJK(中日韩)统一汉字扩充B”的汉字。增加了42711个汉字和多种我国少数民族文字的编码（如藏、蒙古、傣、彝、朝鲜、维吾尔文等）。加上前面GB18030-2000的内容，一共收录了70244个汉字。</p><h3 id="_5-big5编码" tabindex="-1">5. Big5编码 <a class="header-anchor" href="#_5-big5编码" aria-label="Permalink to &quot;5. Big5编码&quot;">​</a></h3><p>在台湾、香港等地区，使用较多的是Big5编码，它的主要特点是收录了繁体字。而从GBK编码开始，已经把Big5中的所有汉字收录进编码了。即对于汉字部分，GBK是Big5的超集，Big5能表示的汉字，在GBK都能找到那些字相应的编码，但他们的编码是不一样的，两个标准不兼容，如GBK中的“啊”字编码是“0xB0A1”，而Big5标准中的编码为“0xB0DA”。我们可以参考这里：<a href="https://www.qqxiuzi.cn/zh/hanzi-big5-bianma.php" target="_blank" rel="noreferrer">BIG5 编码范围, BIG5 编码表 (qqxiuzi.cn)</a></p><h3 id="_6-各个标准的对比" tabindex="-1">6. 各个标准的对比 <a class="header-anchor" href="#_6-各个标准的对比" aria-label="Permalink to &quot;6. 各个标准的对比&quot;">​</a></h3><p>B2312、GBK及GB18030是汉字的国家标准编码，新版向下兼容旧版，各个标准简要说明见下表，目前比较流行的是GBK编码，因为每个汉字只占用2个字节，而且它编码的字符已经能满足大部分的需求，但国家要求一些产品必须支持GB18030标准。</p><img src="'+S+'" alt="image-20230525224416558" style="zoom:50%;"><h2 id="五、unicode编码" tabindex="-1">五、Unicode编码 <a class="header-anchor" href="#五、unicode编码" aria-label="Permalink to &quot;五、Unicode编码&quot;">​</a></h2><h3 id="_1-概述-1" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述-1" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h3><p>由于各个国家或地区都根据使用自己的文字系统制定标准，同一个编码在不同的标准里表示不一样的字符，各个标准互不兼容，而又没有一个标准能够囊括所有的字符，即无法用一个标准表达所有字符。国际标准化组织(ISO)为解决这一问题，它舍弃了地区性的方案，重新给全球上所有文化使用的字母和符号进行编号，对每个字符指定一个唯一的编号(ASCII中原有的字符编号不变)，这些字符的号码从0x000000 到 0x10FFFF（有 1,114,111 即 100 多万个数值，可以表示 100 多万个字符，足够地球人使用了。 ），该编号集被称为 Universal Multiple-Octet Coded Character Set，简称UCS，也被称为<strong>Unicode</strong>。最新版的Unicode标准还包含了表情符号(聊天软件中的部分emoji表情)，可访问Unicode官网了解：<a href="https://home.unicode.org/" target="_blank" rel="noreferrer">Unicode – The World Standard for Text and Emoji</a>。</p><p>Unicode字符集只是对字符进行编号，但具体怎么对每个字符进行编码，Unicode并没指定，因此也衍生出了多种unicode编码方案(Unicode Transformation Format)。</p><h3 id="_2-unicode-编码实现" tabindex="-1">2. UNICODE 编码实现 <a class="header-anchor" href="#_2-unicode-编码实现" aria-label="Permalink to &quot;2. UNICODE 编码实现&quot;">​</a></h3><p>所谓编码实现，就是对于一个数值，怎么表示它。这很奇怪，数值还能怎么表示？比如“中”的 UNICODE 值是 0x4e2d，在 TXT 文件中怎么表示 0x4e2d？直接写入 0x4e2d？不行的。</p><p>比如在 TXT 文件中写入 2 字节数据“ 0x2d 0x4e”，它可以用来表示“中”字吗？这肯定是不行的，它们对应 ASCII 字符“-N”。</p><p>问题的关键在于：怎么断字。在 TXT 文件中， 2 字节数据“ 0x2d 0x4e”是作为一个整体看待，还是拆成两部分看待？</p><p>所以，需要用一定的技巧来表示数值，这就对应不同的编码实现。现在我们知道： 我们知道以下几点：</p><p>（1）ASCII 编码中使用一个字节来表示一个字符，只用到其中的 7 位，最高位恒为 0；</p><p>（2）ANSI 编码中，对于 ASCII 字符仍使用一个字节来表示(BIT7 是 0)，对于非ASCII 字符一般使用 2 个字节来表示，非 ASCII 字符的数值 BIT7 都是 1。</p><p>（3）UNICODE：这就有点复杂了，下面一一了解。</p><h4 id="_2-1-新建测试文件" tabindex="-1">2.1 新建测试文件 <a class="header-anchor" href="#_2-1-新建测试文件" aria-label="Permalink to &quot;2.1 新建测试文件&quot;">​</a></h4><p>先用记事本新建 3 个文件： utf-16_le.txt、 utf-16_be.txt、 utf-8.txt、bom_utf-8.txt，里面的内容都是“ A 中”，保存时编码分别选择“ UTF-16 LE”、“ UTF-16 BE”、“UTF-8”、“带有 BOM 的 UTF-8” ：</p><img src="'+f+'" alt="image-20230525225400864" style="zoom:50%;"><p>一共创建四个文件：</p><img src="'+E+'" alt="image-20230525225601376" style="zoom:80%;"><h4 id="_2-2-使用3个字节表示一个unicode" tabindex="-1">2.2 使用3个字节表示一个Unicode <a class="header-anchor" href="#_2-2-使用3个字节表示一个unicode" aria-label="Permalink to &quot;2.2 使用3个字节表示一个Unicode&quot;">​</a></h4><p>这样不可行，太浪费了。UNICODE 的最大值是 0x10FFFF，那使用 3 个字节来表示一个 Unicode 数值？这当然是很省事的方法，但是会造成浪费，比如字符 A 的 Unicode 值是0x41，总不能也用“0x41 0x00 0x00”这 3 个字节来表示吧，毕竟内存是很珍贵的东西。</p><h4 id="_2-3-ucs-2-little-endian-utf-16-le" tabindex="-1">2.3 UCS-2 Little endian/UTF-16 LE <a class="header-anchor" href="#_2-3-ucs-2-little-endian-utf-16-le" aria-label="Permalink to &quot;2.3 UCS-2 Little endian/UTF-16 LE&quot;">​</a></h4><p>每个 Unicode 值用 3 字节来表示有点浪费，那只用 2 字节呢？它可以表示2^16=65536 个字符，全世界常用的字符都可以表示了。</p><p>Little endian 表示小字节序，数值中权重低的字节放在前面，比如字符“ A 中 ”在 TXT 文件中的数值如下，其中的“ A ”使用“ 0x41 0x00 ”两字节表示；“ 中 ”使用“ 0x2d 0x4e ”两字节表示。文件开头的“ 0xff 0xfe ”表示“UTF-16 LE”。</p><img src="'+T+'" alt="image-20230525225937673" style="zoom:50%;"><h4 id="_2-4-ucs-2-big-endian-utf-16-be" tabindex="-1">2.4 UCS-2 Big endian/UTF-16 BE <a class="header-anchor" href="#_2-4-ucs-2-big-endian-utf-16-be" aria-label="Permalink to &quot;2.4 UCS-2 Big endian/UTF-16 BE&quot;">​</a></h4><p>Big endian 表示大字节序，数值中权重低的字节放在后面，比如字符“ A中 ”在 TXT 文件中的数值如下，其中的“ A ”使用“ 0x00 0x41 ”两字节表示；“ 中 ”使用“ 0x4e 0x2d ”两字节表示。文件开头的“ 0xfe 0xff ”表示“UTF-16 BE”。</p><img src="'+G+'" alt="image-20230525230130328" style="zoom:50%;"><h4 id="_2-5-utf8" tabindex="-1">2.5 UTF8 <a class="header-anchor" href="#_2-5-utf8" aria-label="Permalink to &quot;2.5 UTF8&quot;">​</a></h4><h5 id="_2-5-1-简介" tabindex="-1">2.5.1 简介 <a class="header-anchor" href="#_2-5-1-简介" aria-label="Permalink to &quot;2.5.1 简介&quot;">​</a></h5><p>UTF-8 是目前 Unicode 字符集中使用得最广的编码方式，目前大部分网页文件已使用 UTF-8 编码，如使用浏览器查看百度首页源文件，可以在前几行 HTML 代码中找到如下代码：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> http-equiv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Content-Type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text/html;charset=utf-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中“charset”等号后面的“utf-8”即表示该网页字符的编码方式 UTF-8。 UTF-8 也是一种变长的编码方式，它的编码有 1、 2、 3、 4 字节长度的方式，每个 Unicode 字符根据自己的编号范围去进行对应的编码，见表格 UTF-8 编码原理 _x 的位置用于填充 Unicode 编号。它的编码符合以下规律：</p><p>（1）对于 UTF-8 单字节的编码，该字节的第 1 位设为 0(从左边数起第 1 位，即最高位)，剩余的位用来写入字符的 Unicode 编号。即对于 Unicode 编号从 0x0000 0000 - 0x0000 007F 的字符， UTF-8 编码只需要 1 个字节，因为这个范围 Unicode 编号的字符与 ASCII 码完全相同，所以 UTF-8 兼容了 ASCII 码表。</p><p>（2）对于 UTF-8 使用 N 个字节的编码 (N&gt;1)，第一个字节的前 N 位设为 1，第 N+1 位设为 0，后面字节的前两位都设为 10，这 N 个字节的其余空位填充该字符的 Unicode 编号，高位用0 补足。</p><img src="'+N+'" alt="image-20230525232151415" style="zoom:50%;"><p>注意：实际上 utf-8 编码长度最大为四个字节，所以最多只能表示 Unicode 编码值的二进制数为 21 位的 Unicode 字符。但是已经能表示所有的 Unicode 字符，因为 Unicode 的最大码位 0x10FFFF 也只有 21 位。</p><p>UTF-8 解码的时候以字节为单位去看，如果第一个字节的 bit 位以 0 开头，那就是 ASCII 字符，以单字节进行解析。如果第一个字节的数据位以“110”开头，就按双字节进行解析， 3、 4 字节的解析方法类似。UTF-8 的优点是兼容了 ASCII 码，节约空间，且没有字节顺序的问题，它直接根据第 1 个字节前面数据位中连续的 1 个数决定后面有多少个字节。不过使用 UTF-8 编码汉字平均需要 3 个字节，比 GBK 编码要多一个字节。</p><h5 id="_2-5-2-实例分析" tabindex="-1">2.5.2 实例分析 <a class="header-anchor" href="#_2-5-2-实例分析" aria-label="Permalink to &quot;2.5.2 实例分析&quot;">​</a></h5><p>在上面 2 种方法中，每一个 Unicode 使用 2 字节来表示，这有 3 个缺点：表示的字符数量有限、对于 ASCII 字符有空间浪费、如果文件中有某个字节丢失，这会使得后面所有字符都因为错位而无法显示。使用 UTF8 可以解决上述所有问题。 UTF8 是变长的编码方法，有 2 种 UTF8格式的文件：带有头部、不带头部。</p><img src="'+y+'" alt="image-20230525230541353" style="zoom:50%;"><p>对于其中的 ASCII 字符，在 UTF8 文件中直接用其 ASCII 码来表示，比如上图中的 0x41 表示字符 A。上图中的 3 个字节“ 0xe4 0xb8 0xad”表示的数值是 0x4e2d，对应“中”的 Unicode 码。对于非 ASCII 字符，使用变长的编码：每一个字节的高位都自带长度信息。如下图：</p><img src="'+K+'" alt="image-20230525230717931" style="zoom:33%;"><p>（1）0xe4 的二进制是“ 11100100”，高位有 3 个 1，表示从当前字节起有 3 字节参与表示 Unicode ；</p><p>（2）0xb8 的二进制是“10111000”，高位有 1 个 1，表示从当前字节起有 1 字节参与表示 Unicode ；</p><p>（3）0xad 的二进制是“10101101”，高位有 1 个 1，表示从当前字节起有 1 字节参与表示 Unicode ；</p><p>除去高位的“ 1110”、“ 10”、“ 10”后，剩下的二进制数组合起来得到“ 01001110001101 ”，它就是 0x4e2d，即“中”的 UNICODE 值。使用 UTF8 编码时，即使 TXT 文件中丢失了某些数据，也只会影响到当前字符的显示，后面的字符不受影响。</p><h3 id="_3-其他的一些编码格式" tabindex="-1">3. 其他的一些编码格式 <a class="header-anchor" href="#_3-其他的一些编码格式" aria-label="Permalink to &quot;3. 其他的一些编码格式&quot;">​</a></h3><h4 id="_3-1-utf32" tabindex="-1">3.1 UTF32 <a class="header-anchor" href="#_3-1-utf32" aria-label="Permalink to &quot;3.1 UTF32&quot;">​</a></h4><p>对 Unicode 字符集编码，最自然的就是 UTF-32 方式了。编码时，它直接对 Unicode 字符集里的每个字符都用 4 字节来表示，转换方式很简单，直接将字符对应的编号数字转换为 4 字节的二进制数。如表格 UTF-32 编码示例 ，由于 UTF-32 把每个字符都用要 4 字节来存储，因此 UTF-32 不兼容 ASCII 编码，也就是说 ASCII 编码的文件用 UTF-32 标准来打开会成为乱码。</p><img src="'+v+'" alt="image-20230525231341589" style="zoom:50%;"><p>对 UTF-32 数据进行解码的时候，以 4 个字节为单位进行解析即可，根据编码可直接找到 Unicode 字符集中对应编号的字符。UTF-32 的优点是编码简单，解码也很方便，读取编码的时候每次都直接读 4 个字节，不需要加其它的判断。它的缺点是浪费存储空间，大量常用字符的编号只需要 2 个字节就能表示。其次，在存储的时候需要指定字节顺序，是高位字节存储在前 (大端格式)，还是低位字节存储在前 (小端格式)。</p><h4 id="_3-2-utf-16" tabindex="-1">3.2 UTF-16 <a class="header-anchor" href="#_3-2-utf-16" aria-label="Permalink to &quot;3.2 UTF-16&quot;">​</a></h4><p>针对 UTF-32 的缺点，人们改进出了 UTF-16 的编码方式，如下表：</p><img src="'+w+'" alt="image-20230525231656845" style="zoom:50%;"><p>它采用 2 字节或 4 字节的变长编码方式 (UTF-32 定长为 4 字节)。对 Unicode 字符编号在 0 到 65535 的统一用 2 个字节来表示，将每个字符的编号转换为 2 字节的二进制数，即从 0x0000 到 0xFFFF。而由于 Unicode 字符集在 0xD800-0xDBFF 这个区间是没有表示任何字符的，所以 UTF-16 就利用这段空间，对Unicode 中编号超出 0xFFFF 的字符，利用它们的编号做某种运算与该空间建立映射关系，从而利用该空间表示 4 字节扩展。</p><p>注意下面这个字：</p><img src="'+V+'" alt="image-20230525233015533" style="zoom:50%;"><p>TLHH(不支持 GB18030 码的输入法无法找到该字，我们是可搜索它的 Unicode 编号找到这个字)UTF-16 解码时，按两个字节去读取，如果这两个字节不在 0xD800 到 0xDFFF 范围内，那就是双字节编码的字符，以双字节进行解析，找到对应编号的字符。如果这两个字节在 0xD800 到0xDFFF 之间，那它就是四字节编码的字符，以四字节进行解析，找到对应编号的字符。</p><p>UTF-16 编码的优点是相对 UTF-32 节约了存储空间，缺点是仍不兼容 ASCII 码，仍有大小端格式问题。</p><h3 id="_4-bom" tabindex="-1">4. BOM <a class="header-anchor" href="#_4-bom" aria-label="Permalink to &quot;4. BOM&quot;">​</a></h3><p>刚才我们了解记事本支持的几种编码格式的时候，有提到过头部这个概念，这是因为 UTF 系列有多种编码方式，而且对于 UTF-16 和 UTF-32 还有大小端的区分，那么计算机软件在打开文档的时候到底应该用什么编码方式去解码呢？有的人就想到在文档最前面加标记，一种标记对应一种编码方式，这些标记就叫做 BOM(Byte Order Mark)，它们位于文本文件的开头，见下表：</p><img src="'+D+'" alt="image-20230525232454881" style="zoom:50%;"><p>注意 BOM 是对 Unicode 的几种编码而言的， ANSI 编码没有 BOM。但由于带 BOM 的设计很多规范不兼容，不能跨平台，所以这种带 BOM 的设计没有流行起来。Linux 系统下默认不带 BOM。</p><blockquote><p>参考资料</p><ul><li>字符编码参考网站</li></ul><table><tbody><tr><td align="left"><a href="https://www.qqxiuzi.cn/daohang.htm" target="_blank">千千秀字 (qqxiuzi.cn)</a></td><td align="left">字符编码及转换测试</td></tr><tr><td align="left"><a href="https://home.unicode.org/" target="_blank">Unicode – The World Standard for Text and Emoji</a></td><td align="left">Unicode官网</td></tr></tbody></table></blockquote>',177)])])}const W=e(P,[["render",Q]]);export{Y as __pageData,W as default};
